#!/bin/bash
# Regenerate translation/SYMBOLS.md mechanically from nm -D of the C and Rust .so's.
R="$(cd "$(dirname "$0")" && pwd)"
OUT="$R/translation/SYMBOLS.md"
BACKENDS="blake sha2 shake haraka"
SECPARS="128s 128f 192s 192f 256s 256f"
THASHES="robust simple"

{
echo "# SYMBOLS.md -- exported-symbol parity (\`nm -D\`)"
echo
echo "Generated by \`gen_symbols.sh\`.  The C build produces three shared objects:"
echo
echo "* \`app/libsphincs_core_det.so\` -- core (\`address.c fors.c merkle.c sign.c utils.c\`"
echo "  \`utilsx1.c wots.c wotsx1.c\`) **+ \`rng.c\`** (NIST AES-256-CTR-DRBG \`randombytes\`)"
echo "* \`app/libsphincs_core.so\`     -- the same core **+ \`randombytes.c\`** (\`/dev/urandom\`)"
echo "* \`lib/<backend>/lib<backend>.so\` -- the selected hash backend + \`thash_<backend>_<THASH>.c\`"
echo "  (+ a second copy of \`utils.c\` for blake/sha2)"
echo
echo "The Rust crate builds **one** cdylib, \`libsphincs_core_det.so\`, which therefore has"
echo "to export the union of \`libsphincs_core_det.so\` and \`lib<backend>.so\`."
echo "\`libsphincs_core.so\` adds no new symbol names (its \`randombytes\` is the same name"
echo "with the \`randombytes.c\` body; the deterministic variant is the one the Rust \`[lib]\`"
echo "name selects, so \`rng.c\`'s \`randombytes\` is the one that is exported)."
echo
echo "## Result per configuration"
echo
echo "\`C\` = union of the two C \`.so\`s, \`Rust\` = the Rust cdylib."
echo "\"missing\" = defined in C, absent from Rust -> **must be 0**."
echo
echo "| # | backend | secpar | thash | C syms | Rust syms | missing |"
echo "|---|---------|--------|-------|--------|-----------|---------|"
i=0
totmiss=0
for b in $BACKENDS; do for s in $SECPARS; do for t in $THASHES; do
  i=$((i+1))
  CB="$R/cbuild/$b-$s-$t"
  [ -f "$CB/app/libsphincs_core_det.so" ] || "$R/build_c.sh" "$b" "$s" "$t" >/dev/null 2>&1
  ( cd "$R/translation" && cargo build --release --no-default-features --features "$b,$t,$s" >/dev/null 2>&1 )
  csyms=$( { nm -D --defined-only "$CB/app/libsphincs_core_det.so"; \
             nm -D --defined-only "$CB/app/libsphincs_core.so"; \
             nm -D --defined-only "$CB/lib/$b/lib$b.so"; } | awk '{print $3}' | grep -v '^$' | sort -u )
  rsyms=$(nm -D --defined-only "$R/translation/target/release/libsphincs_core_det.so" | awk '{print $3}' | sort -u)
  miss=$(comm -23 <(echo "$csyms") <(echo "$rsyms") | tr '\n' ' ')
  nm_=$(comm -23 <(echo "$csyms") <(echo "$rsyms") | grep -c . )
  totmiss=$((totmiss+nm_))
  echo "| $i | $b | $s | $t | $(echo "$csyms"|wc -l) | $(echo "$rsyms"|wc -l) | ${nm_}${miss:+ -- $miss} |"
done; done; done
echo
echo "**Total missing symbols across all 48 C configurations: $totmiss**"
echo
echo "## The full C symbol list (default config \`blake / 128f / simple\`)"
echo
echo '```'
{ nm -D --defined-only "$R/cbuild/blake-128f-simple/app/libsphincs_core_det.so"; \
  nm -D --defined-only "$R/cbuild/blake-128f-simple/app/libsphincs_core.so"; \
  nm -D --defined-only "$R/cbuild/blake-128f-simple/lib/blake/libblake.so"; } \
  | awk '{printf "%s %s\n", $2, $3}' | sort -u -k2
echo '```'
} > "$OUT"
echo "wrote $OUT"
